<?php use App\Core\Csrf; use App\Helpers\ViewHelper; ?><div class="section-heading"><div><p class="eyebrow">Phân loại</p><h2>Danh mục sách</h2></div></div><?php if (!empty($error)): ?><div class="notice"><?= ViewHelper::escape($error) ?></div><?php endif; ?><form class="form-card" method="post" action="/admin/categories"><h3>Thêm danh mục</h3><?= Csrf::field() ?><label for="category-name">Tên danh mục</label><input id="category-name" name="name" type="text" required><label for="category-slug">Slug</label><input id="category-slug" name="slug" type="text" pattern="[a-z0-9]+(?:-[a-z0-9]+)*" required><label for="category-description">Mô tả</label><textarea id="category-description" name="description" rows="3"></textarea><button class="button button-primary" type="submit">Tạo danh mục</button></form><div class="table-wrap"><table class="admin-table"><thead><tr><th>Tên danh mục</th><th>Slug</th><th>Mô tả</th><th>Thao tác</th></tr></thead><tbody><?php foreach ($categories ?? [] as $category): ?><tr><td><form id="category-update-<?= (int)$category['id'] ?>" method="post" action="/admin/categories/<?= (int)$category['id'] ?>/update"></form><input form="category-update-<?= (int)$category['id'] ?>" type="hidden" name="_csrf" value="<?= ViewHelper::escape(Csrf::token()) ?>"><input form="category-update-<?= (int)$category['id'] ?>" name="name" value="<?= ViewHelper::escape($category['name']) ?>" required></td><td><input form="category-update-<?= (int)$category['id'] ?>" name="slug" value="<?= ViewHelper::escape($category['slug']) ?>" required></td><td><input form="category-update-<?= (int)$category['id'] ?>" name="description" value="<?= ViewHelper::escape($category['description'] ?? '') ?>"></td><td><div class="action-group"><button class="action-button" form="category-update-<?= (int)$category['id'] ?>" type="submit">Lưu</button><form method="post" action="/admin/categories/<?= (int)$category['id'] ?>/delete"><?= Csrf::field() ?><button class="action-button action-button-danger" type="submit">Xóa</button></form></div></td></tr><?php endforeach; ?></tbody></table></div>
